import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    m = next(it)

    # For each designated position x and right endpoint r, store the
    # largest left endpoint among constraints for x ending at or before r.
    best = [[0] * (n + 1) for _ in range(n + 1)]
    for _ in range(m):
        l = next(it)
        r = next(it)
        x = next(it)
        if l > best[x][r]:
            best[x][r] = l
    for x in range(1, n + 1):
        row = best[x]
        for r in range(1, n + 1):
            if row[r - 1] > row[r]:
                row[r] = row[r - 1]

    # Binomial coefficients for interleaving the left and right parts.
    comb = [[1] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1

    for length in range(1, n + 1):
        for l in range(1, n - length + 2):
            r = l + length - 1
            total = 0
            for k in range(l, r + 1):
                # If k is the maximum of [l,r], it must not be the
                # maximum of any constrained interval contained therein.
                if best[k][r] >= l:
                    continue
                total += dp[l][k - 1] * dp[k + 1][r] * comb[length - 1][k - l]
            dp[l][r] = total % MOD

    print(dp[1][n])

solve()

