import sys
MOD=998244353

def factor(x):
    d={}
    p=2
    while p*p<=x:
        while x%p==0:
            d[p]=d.get(p,0)+1
            x//=p
        p+=1
    if x>1:
        d[x]=d.get(x,0)+1
    return d

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]
    fs=[factor(x) for x in data[1:]]
    primes=set()
    for f in fs:
        primes.update(f)
    ans=1
    for p in primes:
        es=[f.get(p,0) for f in fs]
        limit=sum(es)
        pw=[1]*(limit+1)
        for i in range(1,limit+1):
            pw[i]=pw[i-1]*p%MOD
        dp={(x,int(x==0)):pw[x] for x in range(limit+1)}
        for e in es:
            nd={}
            for (x,seen),v in dp.items():
                if e==0:
                    ys=(x,)
                elif x<e:
                    ys=(x+e,)
                else:
                    ys=(x+e,x-e)
                for y in ys:
                    key=(y,int(bool(seen or y==0)))
                    nd[key]=(nd.get(key,0)+v*pw[y])%MOD
            dp=nd
        ways=sum(v for (x,seen),v in dp.items() if seen)%MOD
        ans=ans*ways%MOD
    print(ans)

main()

