import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    vals = data[1:]
    limit = max(vals)
    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for v in range(p * p, limit + 1, p):
                if spf[v] == v:
                    spf[v] = p
    xor_sum = 0
    for a in vals:
        cnt = 0
        while a > 1:
            a //= spf[a]
            cnt += 1
        xor_sum ^= cnt
    print('Anna' if xor_sum else 'Bruno')

main()

