from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            buckets[b].append((a, i))

        # Largest and second-largest active left endpoints among pairs
        # whose right endpoint is at most the current subarray endpoint.
        largest = second = 0
        largest_count = 0
        largest_owner = -1
        gains = [0] * len(conflictingPairs)
        base = 0

        for r in range(1, n + 1):
            for a, idx in buckets[r]:
                if a > largest:
                    second = largest
                    largest = a
                    largest_count = 1
                    largest_owner = idx
                elif a == largest:
                    largest_count += 1
                elif a > second:
                    second = a

            # Valid starts are larger than the greatest active left endpoint.
            base += r - largest
            if largest_count == 1:
                # Removing the sole pair imposing this bound relaxes it to second.
                gains[largest_owner] += largest - second

        return base + max(gains, default=0)

