import sys

def main():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())
    edges = []
    for _ in range(M):
        a, b, c = map(int, input().split())
        edges.append((a-1, b-1, c))

    queries = []
    closed = [False] * M
    for _ in range(Q):
        q = list(map(int, input().split()))
        if q[0] == 1:
            idx = q[1]-1
            closed[idx] = True
            queries.append((1, idx))
        else:
            queries.append((2, q[1]-1, q[2]-1))

    INF = 10**30
    d = [[INF] * N for _ in range(N)]
    for i in range(N):
        d[i][i] = 0
    for idx, (a, b, c) in enumerate(edges):
        if not closed[idx]:
            d[a][b] = d[b][a] = c

    for k in range(N):
        dk = d[k]
        for i in range(N):
            dik = d[i][k]
            if dik == INF:
                continue
            di = d[i]
            for j in range(N):
                v = dik + dk[j]
                if v < di[j]:
                    di[j] = v

    ans = []
    for q in reversed(queries):
        if q[0] == 2:
            value = d[q[1]][q[2]]
            ans.append(str(value if value < INF else -1))
        else:
            a, b, c = edges[q[1]]
            col_a = [d[i][a] for i in range(N)]
            col_b = [d[i][b] for i in range(N)]
            row_a = d[a][:]
            row_b = d[b][:]
            for i in range(N):
                di = d[i]
                ia = col_a[i] + c
                ib = col_b[i] + c
                for j in range(i, N):
                    old = di[j]
                    x = ia + row_b[j]
                    if x < old:
                        old = x
                    x = ib + row_a[j]
                    if x < old:
                        old = x
                    di[j] = old
                    d[j][i] = old
    sys.stdout.write('\n'.join(reversed(ans)))

if __name__ == '__main__':
    main()

