import sys, math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[:2]
    machines = []
    pos = 2
    for _ in range(n):
        a, p, b, q = data[pos:pos + 4]
        pos += 4
        machines.append((a, p, b, q))

    def minimum_cost(k, a, p, b, q):
        if k == 0:
            return 0

        # For x machines of type S, the least useful number of T machines is
        # ceil((k - a*x)/b). Its behavior repeats linearly when x increases
        # by b/gcd(a,b), so only the endpoints of each residue class matter.
        period = b // math.gcd(a, b)
        max_x_with_positive_remainder = (k - 1) // a
        best = 10**30
        for residue in range(min(period - 1, max_x_with_positive_remainder) + 1):
            max_t = (max_x_with_positive_remainder - residue) // period
            for t in (0, max_t):
                x = residue + t * period
                y = (k - a * x + b - 1) // b
                best = min(best, x * p + y * q)

        # The all-S option can reach the target with no T machines.
        x = (k + a - 1) // a
        return min(best, x * p)

    def feasible(k):
        total = 0
        for a, p, b, q in machines:
            total += minimum_cost(k, a, p, b, q)
            if total > budget:
                return False
        return True

    low, high = 0, 100 * budget + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

