class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        good = [False] * (n + 1)
        for t in range(1, n + 1):
            y = t
            steps = 0
            while y != 1:
                y = y.bit_count()
                steps += 1
            good[t] = steps + 1 <= k

        ans = 0
        for t in range(1, n + 1):
            if not good[t]:
                continue
            count = 0
            used = 0
            for i, ch in enumerate(s):
                if ch == '1':
                    rem = n - i - 1
                    need = t - used
                    if 0 <= need <= rem:
                        count += comb[rem][need]
                    used += 1
            ans = (ans + count) % MOD
        return ans

