                out[i][c]|=1<<j
                inc[j][c]|=1<<i
    d=[[-1]*n for _ in range(n)]
    unseen=[(1<<n)-1 for _ in range(n)]
    q=deque()
    for i in range(n):
        d[i][i]=0; unseen[i]&=~(1<<i);q.append((i,i))
