            im=inc[a][c]
            jm=out[b][c]
            while im:
                bit=im&-im; im-=bit
                i=bit.bit_length()-1
                cand=jm & unseen[i]
                if cand:
                    unseen[i]^=cand
                    while cand:
                        bj=cand&-cand; cand-=bj
                        j=bj.bit_length()-1
                        d[i][j]=nd;q.append((i,j))
