import sys, heapq

def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    it=iter(data)
    H=next(it); W=next(it); X=next(it)
    P=next(it)-1; Q=next(it)-1
    a=[next(it) for _ in range(H*W)]
    start=P*W+Q
    strength=a[start]
    seen=bytearray(H*W); seen[start]=1
    heap=[]
    def add(v):
        if not seen[v]:
            seen[v]=1
            heapq.heappush(heap,(a[v],v))
    for r,c in ((P-1,Q),(P+1,Q),(P,Q-1),(P,Q+1)):
        if 0<=r<H and 0<=c<W:add(r*W+c)
    while heap:
        val,v=heap[0]
        if val*X>=strength:break
        heapq.heappop(heap)
        strength+=val
        r,c=divmod(v,W)
        if r:add(v-W)
        if r+1<H:add(v+W)
        if c:add(v-1)
        if c+1<W:add(v+1)
    print(strength)
