class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = []
        low = []
        for i in range(m):
            c = pow(10, n - 1 - i, k)
            if n - 1 - i != i:
                c = (c + pow(10, i, k)) % k
            coeff.append(c)
            low.append(1 if i == 0 else 0)

        dp = [0] * (m + 1)
        dp[m] = 1  # only residue zero is achievable with no variables
        for i in range(m - 1, -1, -1):
            mask = 0
            for r in range(k):
                if (dp[i + 1] >> r) & 1:
                    for d in range(low[i], 10):
                        mask |= 1 << ((r + d * coeff[i]) % k)
            dp[i] = mask

        digits = ['0'] * n
        rem = 0
        for i in range(m):
            c = coeff[i]
            for d in range(9, low[i] - 1, -1):
                need = (-(rem + d * c)) % k
                if (dp[i + 1] >> need) & 1:
                    digits[i] = digits[n - 1 - i] = str(d)
                    rem = (rem + d * c) % k
                    break
        return ''.join(digits)

