from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        next_greater = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            next_greater[i] = stack[-1] if stack else n
            stack.append(i)

        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        levels = n.bit_length()
        jump = [next_greater]
        aggregate = [[nums[i] * (next_greater[i] - i) - (prefix[next_greater[i]] - prefix[i]) for i in range(n)]]
        for _ in range(1, levels):
            previous_jump = jump[-1]
            previous_aggregate = aggregate[-1]
            current_jump = [n] * n
            current_aggregate = [0] * n
            for i in range(n):
                middle = previous_jump[i]
                if middle < n:
                    current_jump[i] = previous_jump[middle]
                    current_aggregate[i] = previous_aggregate[i] + previous_aggregate[middle]
            jump.append(current_jump)
            aggregate.append(current_aggregate)

        def required_operations(left, right):
            position = left
            total = 0
            for level in range(levels - 1, -1, -1):
                destination = jump[level][position]
                if destination <= right:
                    total += aggregate[level][position]
                    position = destination
            end = min(right + 1, next_greater[position])
            total += nums[position] * (end - position) - (prefix[end] - prefix[position])
            return total

        answer = 0
        for left in range(n):
            low, high = left, n
            while low + 1 < high:
                middle = (low + high) // 2
                if required_operations(left, middle) <= k:
                    low = middle
                else:
                    high = middle
            answer += low - left + 1
        return answer

