class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter

        counts = Counter(s)
        freq = [counts[chr(ord('a') + i)] for i in range(26)]
        answer = len(s)

        # Try each positive frequency for the characters kept in the result.
        for target in range(1, max(freq) + 1):
            # carry is the number of characters changed from this letter
            # into the next one.
            dp = {0: 0}
            for count in freq:
                nxt = {}
                for carry, cost in dp.items():
                    available = count + carry
                    for final_count in (0, target):
                        # Consider deleting excess, forwarding all available
                        # characters, or forwarding just the excess over target.
                        for forwarded in {0, available, max(0, available - final_count)}:
                            new_cost = cost + forwarded + abs(available - forwarded - final_count)
                            if new_cost < nxt.get(forwarded, 10**9):
                                nxt[forwarded] = new_cost
                dp = nxt
            answer = min(answer, dp.get(0, 10**9))

        return answer

