from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        x = p.index('*')
        y = p.index('*', x + 1)
        parts = (p[:x], p[x + 1:y], p[y + 1:])
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))

            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        a_occ, b_occ, c_occ = map(occurrences, parts)
        la, lb, lc = map(len, parts)
        ans = n + 1

        for a in a_occ:
            bi = bisect_left(b_occ, a + la)
            if bi == len(b_occ):
                continue
            b = b_occ[bi]
            ci = bisect_left(c_occ, b + lb)
            if ci == len(c_occ):
                continue
            c = c_occ[ci]
            ans = min(ans, c + lc - a)

        return -1 if ans == n + 1 else ans

