def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it); m = next(it)
    graph = [[] for _ in range(n)]
    for _ in range(m):
        x = next(it)-1; y = next(it)-1; z = next(it)
        graph[x].append((y,z))
        graph[y].append((x,z))

    value = [None] * n
    ans = [0] * n
    for start in range(n):
        if value[start] is not None:
            continue
        value[start] = 0
        comp = []
        stack = [start]
        while stack:
            v = stack.pop()
            comp.append(v)
            for u, z in graph[v]:
                want = value[v] ^ z
                if value[u] is None:
                    value[u] = want
                    stack.append(u)
                elif value[u] != want:
                    print(-1)
                    return
        size = len(comp)
        shift = 0
        for bit in range(31):
            ones = sum((value[v] >> bit) & 1 for v in comp)
            if ones > size - ones:
                shift |= 1 << bit
        for v in comp:
            ans[v] = value[v] ^ shift
    print(*ans)

