class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        min_prefix = [None] * k
        min_prefix[0] = 0
        prefix = 0
        best = -10**30

        for i, value in enumerate(nums, 1):
            prefix += value
            residue = i % k
            previous_min = min_prefix[residue]

            if previous_min is not None:
                best = max(best, prefix - previous_min)

            if previous_min is None or prefix < previous_min:
                min_prefix[residue] = prefix

        return best

