from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        tree = [None] * (4 * n)

        def value(line, x):
            return line[0] * x + line[1]

        def add(node, left, right, line):
            if tree[node] is None:
                tree[node] = line
                return
            mid = (left + right) // 2
            current = tree[node]
            if value(line, mid) > value(current, mid):
                tree[node], line = line, current
                current = tree[node]
            if left == right:
                return
            if value(line, left) > value(current, left):
                add(node * 2, left, mid, line)
            elif value(line, right) > value(current, right):
                add(node * 2 + 1, mid + 1, right, line)

        def query(node, left, right, x):
            line = tree[node]
            best = value(line, x) if line is not None else -1
            if left == right:
                return best
            mid = (left + right) // 2
            if x <= mid:
                child = node * 2
                if tree[child] is not None:
                    best = max(best, query(child, left, mid, x))
            else:
                child = node * 2 + 1
                if tree[child] is not None:
                    best = max(best, query(child, mid + 1, right, x))
            return best

        add(1, 0, n - 1, (nums[0], 0))
        answer = 0
        for i in range(1, n):
            answer = query(1, 0, n - 1, i)
            add(1, 0, n - 1, (nums[i], answer - i * nums[i]))
        return answer

