class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        from collections import Counter
        cnt = Counter(nums)
        total = sum(nums)
        for x in sorted(cnt, reverse=True):
            rem = total - x
            if rem % 2 == 0:
                y = rem // 2
                if cnt.get(y, 0) >= (2 if y == x else 1):
                    return x
        return 0

