class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        if all(x == 0 for x in nums):
            return 0

        limit = max(nums)
        mask = (1 << (limit + 1)) - 1
        attainable = [1] * len(nums)  # Bit s indicates whether sum s is attainable.

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                attainable[i] = (attainable[i] | (attainable[i] << value)) & mask

            if all((attainable[i] >> nums[i]) & 1 for i in range(len(nums))):
                return k

        return -1

