class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq
        limit = 10 ** len(str(n))
        low = limit // 10
        is_prime = bytearray(b'\x01') * limit
        is_prime[0] = 0
        if limit > 1:
            is_prime[1] = 0
        for p in range(2, int(limit ** 0.5) + 1):
            if is_prime[p]:
                is_prime[p*p:limit:p] = b'\x00' * (((limit - 1 - p*p) // p) + 1)
        if is_prime[n] or is_prime[m]:
            return -1
        dist = {n: n}
        pq = [(n, n)]
        powers = [10 ** i for i in range(len(str(n)))]
        while pq:
            cost, x = heapq.heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost
            for p in powers:
                digit = (x // p) % 10
                for change in (-1, 1):
                    nd = digit + change
                    if not 0 <= nd <= 9:
                        continue
                    y = x + change * p
                    if y < low or y >= limit or is_prime[y]:
                        continue
                    nc = cost + y
                    if nc < dist.get(y, 10**30):
                        dist[y] = nc
                        heapq.heappush(pq, (nc, y))
        return -1

