from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0
        sa = list(range(n))
        rank = nums[:]
        k = 1
        while k < n:
            sa.sort(key=lambda x: (rank[x], rank[x + k] if x + k < n else -1))
            new = [0] * n
            r = 0
            new[sa[0]] = 0
            for t in range(1, n):
                a, b = sa[t - 1], sa[t]
                if rank[a] != rank[b] or (rank[a + k] if a + k < n else -1) != (rank[b + k] if b + k < n else -1):
                    r += 1
                new[b] = r
            rank = new
            if r == n - 1:
                break
            k <<= 1
        pos = [0] * n
        for t, x in enumerate(sa):
            pos[x] = t
        lcp = [0] * n
        h = 0
        for i in range(n):
            p = pos[i]
            if p == 0:
                continue
            j = sa[p - 1]
            while i + h < n and j + h < n and nums[i + h] == nums[j + h]:
                h += 1
            lcp[p] = h
            if h:
                h -= 1
        st = [lcp]
        span = 2
        while span <= n:
            prev = st[-1]
            half = span >> 1
            st.append([min(prev[x], prev[x + half]) for x in range(n - span + 1)])
            span <<= 1
        logs = [0] * (n + 1)
        for x in range(2, n + 1):
            logs[x] = logs[x >> 1] + 1
        z = [0] * n
        z[0] = n
        left = right = 0
        for x in range(1, n):
            if x < right:
                z[x] = min(right - x, z[x - left])
            while x + z[x] < n and nums[z[x]] == nums[x + z[x]]:
                z[x] += 1
            if x + z[x] > right:
                left, right = x, x + z[x]
        ans = 0
        for i in range(1, n - 1):
            first = z[i] >= i
            rank_i = pos[i]
            for j in range(i + 1, n):
                if first:
                    ans += 1
                else:
                    rank_j = pos[j]
                    lo, hi = (rank_i, rank_j) if rank_i < rank_j else (rank_j, rank_i)
                    length = hi - lo
                    q = logs[length]
                    common = min(st[q][lo + 1], st[q][hi - (1 << q) + 1])
                    if common >= j - i:
                        ans += 1
        return ans

