from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(1, n - 1):
            m = n - i
            z = [0] * m
            z[0] = m
            l = r = 0
            for k in range(1, m):
                if k < r:
                    z[k] = min(r - k, z[k - l])
                while k + z[k] < m and nums[i + z[k]] == nums[i + k + z[k]]:
                    z[k] += 1
                if k + z[k] > r:
                    l, r = k, k + z[k]
            first = z_global(nums, i)
            for d in range(1, m):
                if first or z[d] >= d:
                    ans += 1
        return ans

def z_global(a, i):
    n = len(a)
    k = 0
    while i + k < n and a[k] == a[i+k]:
        k += 1
    return k >= i

