class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)
        target = set(targetIndices)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0
        for i, ch in enumerate(source):
            ndp = [neg] * (m + 1)
            gain = 1 if i in target else 0
            for j, val in enumerate(dp):
                if val == neg:
                    continue
                # Retain this character without using it, or delete it if allowed.
                ndp[j] = max(ndp[j], val + gain)
                if j < m and ch == pattern[j]:
                    ndp[j + 1] = max(ndp[j + 1], val)
            dp = ndp
        return dp[m]

