class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        incoming = [[] for _ in range(n)]
        weights = set()
        for a, b, w in edges:
            incoming[b].append((a, w))
            weights.add(w)

        values = sorted(weights)

        def can_reach_all(limit: int) -> bool:
            seen = bytearray(n)
            seen[0] = 1
            stack = [0]
            reached = 1
            while stack:
                v = stack.pop()
                for u, w in incoming[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = 1
                        reached += 1
                        stack.append(u)
            return reached == n

        if not can_reach_all(values[-1]):
            return -1

        lo, hi = 0, len(values) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if can_reach_all(values[mid]):
                hi = mid
            else:
                lo = mid + 1
        return values[lo]

